blocks.text:
server {
    listen 443 ssl;
    server_name status.harbor.test;

    ssl_certificate /etc/pki/tls/certs/harbor.crt;
    ssl_certificate_key /etc/pki/tls/private/harbor.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    root /srv/harbor/site;
    index index.html;
    access_log /var/log/nginx/harbor-access.log;
    error_log /var/log/nginx/harbor-error.log;

    location / {
        try_files $uri $uri/ =404;
    }
}

